<!-- wp:group {"metadata":{"name":"Questions"},"align":"full","style":{"spacing":{"padding":{"top":"var:preset|spacing|60","bottom":"var:preset|spacing|60","left":"var:preset|spacing|edge-space","right":"var:preset|spacing|edge-space"}}},"layout":{"type":"constrained"},"anchor":"faq"} -->
<div class="wp-block-group alignfull" id="faq" style="padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--edge-space);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--edge-space)"><!-- wp:heading {"style":{"typography":{"textAlign":"center"}}} -->
<h2 class="wp-block-heading has-text-align-center"><?php esc_html_e( 'Questions', 'wporg' ); ?></h2>
<!-- /wp:heading -->

<!-- wp:group {"align":"wide","style":{"spacing":{"margin":{"top":"var:preset|spacing|50"},"blockGap":{"top":"36px","left":"64px"}}},"layout":{"type":"grid","minimumColumnWidth":"28rem"}} -->
<div class="wp-block-group alignwide" style="margin-top:var(--wp--preset--spacing--50)"><!-- wp:group {"style":{"spacing":{"blockGap":"10px"}},"layout":{"type":"default"}} -->
<div class="wp-block-group"><!-- wp:heading {"level":3,"style":{"typography":{"fontSize":"18px","fontStyle":"normal","fontWeight":"600","lineHeight":"1.4"}},"fontFamily":"inter"} -->
<h3 class="wp-block-heading has-inter-font-family" style="font-size:18px;font-style:normal;font-weight:600;line-height:1.4"><?php esc_html_e( 'Will it work on my host?', 'wporg' ); ?></h3>
<!-- /wp:heading -->

<!-- wp:paragraph {"textColor":"charcoal-3"} -->
<p class="has-charcoal-3-color has-text-color"><?php _e( 'Yes. Reprint is a regular plugin designed for maximum compatibility. It runs on WordPress 4.7 or newer and PHP 5.6.20 or newer, and needs no SSH or FTP access. If it doesn’t work on your host, <a href="https://github.com/WordPress/reprint/issues" target="_blank">open an issue ↗</a>. Reprint’s goal is to support every host.', 'wporg' ); ?></p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->

<!-- wp:group {"style":{"spacing":{"blockGap":"10px"}},"layout":{"type":"default"}} -->
<div class="wp-block-group"><!-- wp:heading {"level":3,"style":{"typography":{"fontSize":"18px","fontStyle":"normal","fontWeight":"600","lineHeight":"1.4"}},"fontFamily":"inter"} -->
<h3 class="wp-block-heading has-inter-font-family" style="font-size:18px;font-style:normal;font-weight:600;line-height:1.4"><?php esc_html_e( 'How big a site can it copy?', 'wporg' ); ?></h3>
<!-- /wp:heading -->

<!-- wp:paragraph {"textColor":"charcoal-3"} -->
<p class="has-charcoal-3-color has-text-color"><?php esc_html_e( 'As big as the destination can hold. Reprint never packs the site into one archive, so the live server needs no spare disk space and no upload limit applies. It sends files and database rows in parts and saves its place, so a big site only takes longer.', 'wporg' ); ?></p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->

<!-- wp:group {"style":{"spacing":{"blockGap":"10px"}},"layout":{"type":"default"}} -->
<div class="wp-block-group"><!-- wp:heading {"level":3,"style":{"typography":{"fontSize":"18px","fontStyle":"normal","fontWeight":"600","lineHeight":"1.4"}},"fontFamily":"inter"} -->
<h3 class="wp-block-heading has-inter-font-family" style="font-size:18px;font-style:normal;font-weight:600;line-height:1.4"><?php esc_html_e( 'How is it different from other migration plugins?', 'wporg' ); ?></h3>
<!-- /wp:heading -->

<!-- wp:paragraph {"textColor":"charcoal-3"} -->
<p class="has-charcoal-3-color has-text-color"><?php esc_html_e( 'Reprint copies sites of any size, even on shared hosting with strict limits. It sends the site in small parts and saves its progress after each one, so after a broken connection it continues where it stopped. The next copy downloads only the files that changed. And the data goes straight from your site to your machine, never through someone else’s servers.', 'wporg' ); ?></p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->

<!-- wp:group {"style":{"spacing":{"blockGap":"10px"}},"layout":{"type":"default"}} -->
<div class="wp-block-group"><!-- wp:heading {"level":3,"style":{"typography":{"fontSize":"18px","fontStyle":"normal","fontWeight":"600","lineHeight":"1.4"}},"fontFamily":"inter"} -->
<h3 class="wp-block-heading has-inter-font-family" style="font-size:18px;font-style:normal;font-weight:600;line-height:1.4"><?php esc_html_e( 'Does it copy everything?', 'wporg' ); ?></h3>
<!-- /wp:heading -->

<!-- wp:paragraph {"textColor":"charcoal-3"} -->
<p class="has-charcoal-3-color has-text-color"><?php _e( 'The files and the database: posts, pages, media, users, settings, themes, plugins, and their tables, such as WooCommerce orders. It leaves out caches, logs, backup archives, and temporary files. You can also leave files out using the <code>--exclude</code> CLI option. The site keeps changing during the copy, so for a final move, pause orders and uploads and run the pull once more.', 'wporg' ); ?></p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->

<!-- wp:group {"style":{"spacing":{"blockGap":"10px"}},"layout":{"type":"default"}} -->
<div class="wp-block-group"><!-- wp:heading {"level":3,"style":{"typography":{"fontSize":"18px","fontStyle":"normal","fontWeight":"600","lineHeight":"1.4"}},"fontFamily":"inter"} -->
<h3 class="wp-block-heading has-inter-font-family" style="font-size:18px;font-style:normal;font-weight:600;line-height:1.4"><?php esc_html_e( 'Will my live site slow down?', 'wporg' ); ?></h3>
<!-- /wp:heading -->

<!-- wp:paragraph {"textColor":"charcoal-3"} -->
<p class="has-charcoal-3-color has-text-color"><?php esc_html_e( 'Reprint paces itself. The client waits between requests to leave room for your visitors, and the plugin runs nothing in the background.', 'wporg' ); ?></p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->

<!-- wp:group {"style":{"spacing":{"blockGap":"10px"}},"layout":{"type":"default"}} -->
<div class="wp-block-group"><!-- wp:heading {"level":3,"style":{"typography":{"fontSize":"18px","fontStyle":"normal","fontWeight":"600","lineHeight":"1.4"}},"fontFamily":"inter"} -->
<h3 class="wp-block-heading has-inter-font-family" style="font-size:18px;font-style:normal;font-weight:600;line-height:1.4"><?php esc_html_e( 'Is it safe to install on a live site?', 'wporg' ); ?></h3>
<!-- /wp:heading -->

<!-- wp:paragraph {"textColor":"charcoal-3"} -->
<p class="has-charcoal-3-color has-text-color"><?php esc_html_e( 'Installing the plugin starts nothing. Nothing leaves the site until an administrator approves a machine in Tools → Reprint Server, and the plugin from WordPress.org only allows downloads. It can’t change the site. You can remove a machine’s access there at any time.', 'wporg' ); ?></p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->

<!-- wp:group {"style":{"spacing":{"blockGap":"10px"}},"layout":{"type":"default"}} -->
<div class="wp-block-group"><!-- wp:heading {"level":3,"style":{"typography":{"fontSize":"18px","fontStyle":"normal","fontWeight":"600","lineHeight":"1.4"}},"fontFamily":"inter"} -->
<h3 class="wp-block-heading has-inter-font-family" style="font-size:18px;font-style:normal;font-weight:600;line-height:1.4"><?php esc_html_e( 'Will the copied site send email or charge customers?', 'wporg' ); ?></h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p><?php esc_html_e( 'Copying your site doesn’t send email or charge anyone. The risk comes later, when you use the copied site. Plugins that still use your live settings can send order emails to real customers or charge them for subscription renewals. Before using the copied site, disable those plugins or switch them to test accounts.', 'wporg' ); ?></p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->

<!-- wp:group {"style":{"spacing":{"blockGap":"10px"}},"layout":{"type":"default"}} -->
<div class="wp-block-group"><!-- wp:heading {"level":3,"style":{"typography":{"fontSize":"18px","fontStyle":"normal","fontWeight":"600","lineHeight":"1.4"}},"fontFamily":"inter"} -->
<h3 class="wp-block-heading has-inter-font-family" style="font-size:18px;font-style:normal;font-weight:600;line-height:1.4"><?php esc_html_e( 'Is the copy private?', 'wporg' ); ?></h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p><?php esc_html_e( 'You’re in control of that. Reprint transfers your files and database directly from your site to your computer, using your site’s HTTPS connection. The copy then lands in the folder you choose, whether that’s a web root visitors can open or a private folder only you can read.', 'wporg' ); ?></p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->

<!-- wp:group {"style":{"spacing":{"blockGap":"10px"}},"layout":{"type":"default"}} -->
<div class="wp-block-group"><!-- wp:heading {"level":3,"style":{"typography":{"fontSize":"18px","fontStyle":"normal","fontWeight":"600","lineHeight":"1.4"}},"fontFamily":"inter"} -->
<h3 class="wp-block-heading has-inter-font-family" style="font-size:18px;font-style:normal;font-weight:600;line-height:1.4"><?php esc_html_e( 'Does it work with multisite?', 'wporg' ); ?></h3>
<!-- /wp:heading -->

<!-- wp:paragraph {"textColor":"charcoal-3"} -->
<p class="has-charcoal-3-color has-text-color"><?php _e( 'Yes, one site at a time. Each copy becomes a standalone WordPress site. Copying a whole network isn’t supported yet. On the main site, plugin tables such as WooCommerce orders stay behind. <a href="https://developer.wordpress.org/reprint/guides/multisite/" target="_blank">Read the multisite guide ↗</a>.', 'wporg' ); ?></p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->

<!-- wp:group {"style":{"spacing":{"blockGap":"10px"}},"layout":{"type":"default"}} -->
<div class="wp-block-group"><!-- wp:heading {"level":3,"style":{"typography":{"fontSize":"18px","fontStyle":"normal","fontWeight":"600","lineHeight":"1.4"}},"fontFamily":"inter"} -->
<h3 class="wp-block-heading has-inter-font-family" style="font-size:18px;font-style:normal;font-weight:600;line-height:1.4"><?php esc_html_e( 'Can I send changes back to the live site?', 'wporg' ); ?></h3>
<!-- /wp:heading -->

<!-- wp:paragraph {"textColor":"charcoal-3"} -->
<p class="has-charcoal-3-color has-text-color"><?php _e( 'Not yet. The plugin from WordPress.org only downloads. The development build on GitHub can send files and the database back, once an administrator allows it for each machine. <a href="https://developer.wordpress.org/reprint/contributing/push/" target="_blank">Read how pushing works ↗</a>.', 'wporg' ); ?></p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->

<!-- wp:group {"style":{"spacing":{"blockGap":"10px"}},"layout":{"type":"default"}} -->
<div class="wp-block-group"><!-- wp:heading {"level":3,"style":{"typography":{"fontSize":"18px","fontStyle":"normal","fontWeight":"600","lineHeight":"1.4"}},"fontFamily":"inter"} -->
<h3 class="wp-block-heading has-inter-font-family" style="font-size:18px;font-style:normal;font-weight:600;line-height:1.4"><?php esc_html_e( 'What does it cost?', 'wporg' ); ?></h3>
<!-- /wp:heading -->

<!-- wp:paragraph {"textColor":"charcoal-3"} -->
<p class="has-charcoal-3-color has-text-color"><?php esc_html_e( 'Nothing. Reprint is free and open source under the GNU General Public License (GPL), developed in the open on GitHub.', 'wporg' ); ?></p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->

<!-- wp:group {"style":{"spacing":{"blockGap":"10px"}},"layout":{"type":"default"}} -->
<div class="wp-block-group"><!-- wp:heading {"level":3,"style":{"typography":{"fontSize":"18px","fontStyle":"normal","fontWeight":"600","lineHeight":"1.4"}},"fontFamily":"inter"} -->
<h3 class="wp-block-heading has-inter-font-family" style="font-size:18px;font-style:normal;font-weight:600;line-height:1.4"><?php esc_html_e( 'Where do I get help?', 'wporg' ); ?></h3>
<!-- /wp:heading -->

<!-- wp:paragraph {"textColor":"charcoal-3"} -->
<p class="has-charcoal-3-color has-text-color"><?php _e( 'Ask in the <a href="https://wordpress.org/support/plugin/reprint/" target="_blank">Reprint support forum</a> on WordPress.org, and report bugs in the <a href="https://github.com/WordPress/reprint/issues" target="_blank">issue tracker ↗</a> on GitHub.', 'wporg' ); ?></p>
<!-- /wp:paragraph --></div>
<!-- /wp:group --></div>
<!-- /wp:group --></div>
<!-- /wp:group -->

<!-- wp:group {"metadata":{"name":"Get involved"},"align":"full","style":{"spacing":{"padding":{"top":"var:preset|spacing|80","bottom":"var:preset|spacing|80","left":"var:preset|spacing|edge-space","right":"var:preset|spacing|edge-space"}},"elements":{"link":{"color":{"text":"var:preset|color|white"}}}},"backgroundColor":"blueberry-1","textColor":"white","layout":{"type":"constrained"}} -->
